export default function collect({ previous, response, businessUnitId, maxPages }) {
  const s = previous ?? { reviews: [], count: 0, token: null, seen: [], started: false };
  const base = "https://api.trustpilot.com/v1/business-units/" + businessUnitId + "/all-reviews";
  if (!s.started) return { state: { ...s, started: true }, more: true, url: base, reviews: [] };
  if (!response || typeof response !== "object" || !Array.isArray(response.reviews))
    throw Error("Invalid Trustpilot response");
  const reviews = [...s.reviews, ...response.reviews],
    token = response.nextPageToken;
  if (token == null) return { state: { ...s, reviews }, more: false, url: base, reviews };
  if (typeof token !== "string" || !token || s.seen.includes(token))
    throw Error("Invalid Trustpilot page token");
  if (s.count + 1 >= maxPages) return { state: { ...s, reviews }, more: false, url: base, reviews };
  return {
    state: { ...s, reviews, count: s.count + 1, token, seen: [...s.seen, token] },
    more: true,
    url: base + "?pageToken=" + encodeURIComponent(token),
    reviews: [],
  };
}

