export default function next({ tasks, previous, confirmation, generalSheet, helpfulSheet }) {
  const s = previous ?? { index: 0, waiting: false };
  if (s.waiting) {
    if (confirmation !== 18) throw Error("Both sheet updates were not confirmed");
    s.index++;
    s.waiting = false;
  }
  if (s.index >= tasks.length)
    return {
      state: s,
      more: false,
      item: {},
      generalRange: "'unused'!A1:ZZZ1",
      helpfulRange: "'unused'!A1:ZZZ1",
    };
  const item = tasks[s.index];
  if (
    !item ||
    !Number.isSafeInteger(item.general?.index) ||
    !Number.isSafeInteger(item.helpful?.index)
  )
    throw Error("Invalid review task");
  const range = (sheet, index) => "'" + sheet.replace(/'/g, "''") + "'!A" + index + ":ZZZ" + index;
  return {
    state: { ...s, waiting: true },
    more: true,
    item,
    generalRange: range(generalSheet, item.general.index),
    helpfulRange: range(helpfulSheet, item.helpful.index),
  };
}

